using System;
using System.Text;
using UnityEngine;
using LWS.TruckSports;
using LWS.TruckBowling;
namespace LWS.TruckDockDiving {
public enum DockPhase {Approach,Flight,Splash,Replay,Result,Complete}
public sealed class DockMatch:SportsEventSession {
 public const string RecordKey="TruckDockDiving.SoloBest.Inches.v1";public int PersonalBest{get;private set;}
 public SportsEventTruck truck;public SportsEventTruck[] staged;public DockSplitVisual split;public DockReplay replay;public SportsEventCamera broadcast;public Collider dock,waterVolume;public ParticleSystem splash;public Transform bestMarker;
 public float edge=0,poolHalfWidth=11,poolLength=130,aftertouchAcceleration=1.2f,aftertouchBudget=2.1f;
 public DockPhase Phase{get;private set;}public int Active{get;private set;}public int Round{get;private set;}public int Winner{get;private set;}=-1;public int Launches{get;private set;}public int Locks{get;private set;}public string Timing{get;private set;}="";public int LastInches{get;private set;}public int[] best=new int[8];public int[,] history=new int[8,3];public int[] extraScores=new int[8];public bool[] finalists=new bool[8];public int CompletedAttempts{get;private set;}
 static readonly Vector3[] ReplayOffsets={new Vector3(7,8,-14),new Vector3(17,4,-2),new Vector3(8,5,-7),new Vector3(0,24,.1f)};static readonly string[] AngleNames={"RUN-UP","SIDE","SPLASH","OVERHEAD"};
 readonly StringBuilder text=new StringBuilder(1200);float timer,flight,used,aiSpeed,aiPressAt,age;int pendingReaction=-1;float reactionDelay;bool rangeReleased,extra,locked,wasBest;string reason="";
 public override string Title=>"TRUCK DOCK DIVING";public override int MinimumPlayers=>1;public override int MaximumPlayers=>8;public override string OptionLabel=>"3 ATTEMPTS · LONGEST VALID JUMP";
 public override string Help=>"DOCK DIVING · THE TRUCK IS THE DIVER\nOne to eight competitors rotate through three attempts. Longest valid jump wins; solo is a personal-best challenge. Tied leaders take extra jumps against each other; each extra-round distance breaks that tie.\n\nDRIVE using your assigned cluster or stick. Opposite throttle brakes before reversing. ACTION jumps: keyboard key shown in setup; whole pad South; shared left LT / shared right RT. Press close to the dock edge for PERFECT timing. Early/late input is weaker; missing input gives a weak automatic jump. Speed and timing determine most of the distance.\n\nIn flight, left/right nudges trajectory. Release forward/back before range correction; total aftertouch is limited. No hovering or repeat jumps. The cab separates visually from the lower chassis over the same physical body.\n\nDistance is forward from the dock edge to the Rigidbody center at FIRST water-volume contact, rounded once to a whole inch. This same integer governs display, records and ties. Sideways distance adds nothing. Outside-pool center or a solid landing is a zero-distance foul. Failed approaches resolve after 30 seconds.\n\nEvery attempt has a recorded, nonphysical replay. Choose camera / speed / rewind, or skip after one second. Replay never reruns scores or forces. Choosing a manual angle or speed keeps the replay available until SKIP / ACTION. AI auto-advances. Pause/disconnect preserves the exact attempt; release inputs and confirm freshly to resume. Configuration survives rematch.";
 public override string Header=>Title+"  ·  "+(extra?"TIEBREAK "+(Round-3):"ROUND "+Round+" / 3")+"  ·  "+setup.players[Active].name;
 public override string Status=>Phase==DockPhase.Approach?"BUILD SPEED  ·  ACTION near the edge  ·  "+Mathf.Max(0,edge-(truck.body.position.z+1.4f)).ToString("F1")+"m TO EDGE":Phase==DockPhase.Flight?Timing+"  ·  AIRBORNE  ·  LIMITED AFTERTOUCH":Phase==DockPhase.Replay?"REPLAY  ·  "+AngleNames[replay.Angle]+"  ·  "+replay.Speed.ToString("F2")+"×  ·  "+Format(LastInches):reason+"  ·  "+Format(LastInches)+(wasBest?"  ·  NEW BEST":"");
 public override string Standings{get{text.Clear();for(int i=0;i<setup.count;i++)text.Append(i==Active?"> ":"").Append(setup.players[i].name).Append("  ").Append(Format(best[i])).Append('\n');if(setup.count==1)text.Append("\nLOCAL SOLO RECORD  ").Append(Format(PersonalBest));return text.ToString();}}
 public int ResultPlace(int slot)=>LWS.TruckSports.SportsResultPlacings.FromFinalTotals(slot,setup.count,best,Winner);
 public bool ResultHadTiebreak=>extra;
 public int ResultPersonalBest=>PersonalBest;
 public int ResultWinningExtraInches=>extra&&Winner>=0&&Winner<setup.count?extraScores[Winner]:0;
 public override string Results{get{text.Clear().Append(setup.count==1?"PERSONAL-BEST CHALLENGE COMPLETE":setup.players[Winner].name+" WINS").Append("\n\n");for(int i=0;i<setup.count;i++){text.Append(setup.players[i].name).Append("   BEST ").Append(Format(best[i])).Append("   | ");for(int j=0;j<3;j++)text.Append("  ").Append(j+1).Append(": ").Append(Format(history[i,j]));text.Append('\n');}if(setup.count==1)text.Append("\nLOCAL SOLO RECORD  ").Append(Format(PersonalBest));if(extra)text.Append("\nExtra jumps resolved the first-place tie.");return text.ToString();}}
 public override bool ReplayControls=>Phase==DockPhase.Replay&&timer>1;
 public static int Inches(float metres)=>Mathf.Max(0,Mathf.RoundToInt(metres/.0254f));public static string Format(int inches)=>(inches/12)+"′ "+(inches%12)+"″";
 public static string Quality(float remaining)=>remaining>2.4f?"EARLY":remaining<-.5f?"LATE":remaining>=.1f&&remaining<=1.1f?"PERFECT":"GOOD";
 protected override void BeginGame(){GetComponent<DockSlang>()?.ResetMatch();PersonalBest=Mathf.Max(0,LWS.TruckSports.SportsPrefs.GetInt(RecordKey,0));Array.Clear(best,0,8);Array.Clear(history,0,history.Length);Array.Clear(finalists,0,8);CompletedAttempts=Launches=Locks=0;Winner=-1;Round=1;Active=0;extra=false;for(int i=0;i<staged.Length;i++){staged[i].slot=i;staged[i].ApplyColor(setup.players[i].color);staged[i].Park(new Vector3(-8-i%2*3,2.6f,-24+i/2*4));staged[i].gameObject.SetActive(i<setup.count);}StartAttempt();}
 void StartAttempt(){pendingReaction=-1;replay.Stop();split.Apply(0);truck.slot=Active;truck.Prepare(new Vector3(0,2.62f,-26),Quaternion.identity);truck.Power(true);staged[Active].gameObject.SetActive(false);for(int i=0;i<setup.count;i++)if(i!=Active)staged[i].gameObject.SetActive(true);float error=setup.players[Active].difficulty==BowlingDifficulty.Easy?2.6f:setup.players[Active].difficulty==BowlingDifficulty.Normal?1.25f:.45f;aiSpeed=setup.players[Active].difficulty==BowlingDifficulty.Easy?16:setup.players[Active].difficulty==BowlingDifficulty.Normal?19:21;aiSpeed+=UnityEngine.Random.Range(-error,error);aiPressAt=.6f+UnityEngine.Random.Range(-error,error);timer=flight=used=age=0;locked=rangeReleased=false;LastInches=0;Timing=reason="";Phase=DockPhase.Approach;replay.Begin();Gate();broadcast.Pose(new Vector3(0,2,-10),new Vector3(9,10,-17),58,true);}
 void Launch(bool automatic){if(Phase!=DockPhase.Approach)return;float remaining=edge-(truck.body.position.z+1.4f);Timing=automatic?"MISSED · AUTO":Quality(remaining);float quality=automatic?.36f:Timing=="PERFECT"?1:Timing=="GOOD"?.86f:Timing=="EARLY"?.57f:.5f;float speed=Mathf.Clamp(truck.body.linearVelocity.z,0,25);float impulse=(8+speed*.28f)*quality;truck.Power(false);truck.body.AddForce(Vector3.up*impulse,ForceMode.VelocityChange);truck.body.AddTorque(new Vector3(-.28f,0,-commands[Active].x*.2f),ForceMode.VelocityChange);Phase=DockPhase.Flight;flight=used=0;rangeReleased=false;Launches++;feedback.PlayAt(4,truck.body.position,0,true);Pulse(Active,.25f,.12f);}
 protected override void Simulate(float dt){timer+=dt;age+=dt;if(pendingReaction>=0){reactionDelay-=dt;if(reactionDelay<=0){feedback.PlayAt(pendingReaction,new Vector3(-18,2,Mathf.Clamp(truck.body.position.z,10,100)),0,true);pendingReaction=-1;}}var drive=commands[Active];bool action=actions[Active];bool ai=setup.players[Active].source==BowlingSource.AI;
  if(Phase==DockPhase.Approach){if(ai){float offset=-truck.body.position.x*.35f-truck.body.linearVelocity.x*.1f;float angle=Mathf.DeltaAngle(0,truck.body.rotation.eulerAngles.y);drive=new Vector2(Mathf.Clamp(offset-angle*.025f,-.35f,.35f),truck.body.linearVelocity.z<aiSpeed?1:0);action=edge-(truck.body.position.z+1.4f)<=aiPressAt;}truck.TickDrive(drive);if(action)Launch(false);else if(edge-(truck.body.position.z+1.4f)<-1.6f)Launch(true);if(age>30||truck.body.position.y< -4||Mathf.Abs(truck.body.position.x)>14)Lock(false,"FAILED APPROACH");}
  else if(Phase==DockPhase.Flight){flight+=dt;if(ai)drive=new Vector2(Mathf.Clamp(-truck.body.position.x*.1f-truck.body.linearVelocity.x*.2f,-.6f,.6f),0);if(Mathf.Abs(drive.y)<.15f)rangeReleased=true;Vector2 touch=new Vector2(drive.x,rangeReleased?drive.y*.65f:0);float cost=touch.magnitude*aftertouchAcceleration*dt;float allowed=Mathf.Min(cost,Mathf.Max(0,aftertouchBudget-used));if(cost>0){float factor=allowed/cost*Mathf.Clamp01((flight-.18f)*3);truck.body.AddForce(new Vector3(touch.x,0,touch.y)*aftertouchAcceleration*factor,ForceMode.Acceleration);truck.body.AddTorque(new Vector3(touch.y*.07f,0,-touch.x*.07f)*factor,ForceMode.Acceleration);used+=allowed;}split.Apply(Mathf.Sin(Mathf.Clamp01(flight/.8f)*Mathf.PI)*.6f);if(age>35||truck.body.position.y< -5||Mathf.Abs(truck.body.position.x)>25||truck.body.position.z>poolLength+5)Lock(false,"OUTSIDE POOL");}
  else if(Phase==DockPhase.Splash){split.Apply(Mathf.MoveTowards(split.Separation,0,dt*2));truck.body.AddForce(-truck.body.linearVelocity*2+Vector3.up*8,ForceMode.Acceleration);if(timer>1.05f){replay.Complete();truck.body.linearVelocity=truck.body.angularVelocity=Vector3.zero;truck.body.isKinematic=true;Phase=DockPhase.Replay;timer=0;if(!replay.Play())FinishReplay();}}
  else if(Phase==DockPhase.Replay){if(replay.Tick(dt,ai)||timer>1&&action)FinishReplay();}
  else if(Phase==DockPhase.Result&&timer>1.8f)NextAttempt();
  if(Phase!=DockPhase.Replay&&Phase!=DockPhase.Result)replay.Sample(truck.transform,split.Separation);
 }
 public void TouchWater(){if(Phase!=DockPhase.Flight||locked)return;var p=truck.body.position;Lock(Mathf.Abs(p.x)<=poolHalfWidth&&p.z>=edge&&p.z<=poolLength,"SPLASH");}
 public void SolidLanding(Collider collider,float speed){if(!Live||locked||Phase!=DockPhase.Flight)return;Lock(false,collider==dock?"EARLY · LANDED ON DOCK":"OUTSIDE POOL");}
 void Lock(bool valid,string message){if(locked||Phase!=DockPhase.Flight&&Phase!=DockPhase.Approach)return;locked=true;Locks++;LastInches=valid?Inches(truck.body.position.z-edge):0;reason=valid?"VALID JUMP":message+" · FOUL";wasBest=LastInches>best[Active];if(wasBest)best[Active]=LastInches;if(valid&&setup.count==1&&LastInches>PersonalBest){PersonalBest=LastInches;LWS.TruckSports.SportsPrefs.SetInt(RecordKey,PersonalBest);LWS.TruckSports.SportsPrefs.Save();}if(extra)extraScores[Active]=LastInches;else history[Active,Round-1]=LastInches;CompletedAttempts++;Phase=DockPhase.Splash;timer=0;truck.Power(false);var p=truck.body.position;splash.transform.position=new Vector3(p.x,0,p.z);splash.Play();if(valid)feedback.PlayAt(2,splash.transform.position,0,true);Pulse(Active,.32f,.16f);pendingReaction=!valid?3:LastInches>Inches(58)?6:LastInches>Inches(43)||wasBest&&LastInches>Inches(35)?5:LastInches<Inches(12)?3:1;reactionDelay=.28f;bestMarker.position=new Vector3(0,.08f,best[Active]*.0254f+edge);Debug.Log("DOCK_ATTEMPT slot="+Active+" round="+Round+" valid="+valid+" inches="+LastInches+" timing="+Timing);}
 void FinishReplay(){replay.Stop();split.Apply(0);Phase=DockPhase.Result;timer=0;Gate();}
 void NextAttempt(){if(!extra){Active++;if(Active>=setup.count){Active=0;Round++;}if(Round>3){if(setup.count==1){Winner=0;Complete();return;}int high=0,count=0;for(int i=0;i<setup.count;i++)high=Mathf.Max(high,best[i]);for(int i=0;i<setup.count;i++){finalists[i]=best[i]==high;if(finalists[i]){count++;Winner=i;}}if(count==1){Complete();return;}extra=true;Array.Clear(extraScores,0,8);Active=FirstFinalist();}}
  else{int next=Active+1;while(next<setup.count&&!finalists[next])next++;if(next<setup.count)Active=next;else{int high=0,count=0;for(int i=0;i<setup.count;i++)if(finalists[i])high=Mathf.Max(high,extraScores[i]);for(int i=0;i<setup.count;i++)if(finalists[i]){finalists[i]=extraScores[i]==high;if(finalists[i]){Winner=i;count++;}}if(count==1){Complete();return;}Round++;Array.Clear(extraScores,0,8);Active=FirstFinalist();}}
  StartAttempt();
 }
 void Complete(){Phase=DockPhase.Complete;EndMatch();}
 int FirstFinalist(){for(int i=0;i<setup.count;i++)if(finalists[i])return i;return 0;}
 public override void ExtraAction(string key){if(Phase!=DockPhase.Replay||timer<1)return;if(key=="replayangle")replay.NextAngle();else if(key=="replayspeed")replay.NextSpeed();else if(key=="replayrewind")replay.Rewind();else if(key=="replayskip")FinishReplay();}
 protected override void Present(float dt){if(broadcast==null||truck==null)return;Vector3 p=Phase==DockPhase.Replay?replay.Position:truck.body.position;if(Phase==DockPhase.Approach)broadcast.Pose(Vector3.Lerp(p,new Vector3(0,2,edge),.35f),new Vector3(7,9,-14));else if(Phase==DockPhase.Replay){broadcast.Pose(p,ReplayOffsets[replay.Angle]);}else if(Phase==DockPhase.Splash&&LastInches>0&&TryGetComponent<DockPoolPresentation>(out var pool)&&pool.ImpactLaunch==Launches)broadcast.Pose(pool.ImpactPoint+Vector3.up*1.5f,new Vector3(12,10,-17),60);else broadcast.Pose(p,new Vector3(12,7,-12),60);}
 protected override void StopGame(){pendingReaction=-1;if(truck!=null){truck.Power(false);if(!truck.body.isKinematic)truck.body.linearVelocity=truck.body.angularVelocity=Vector3.zero;truck.body.isKinematic=true;}replay?.Stop();}
 protected override void StopSounds(){pendingReaction=-1;truck?.StopSound();}
 protected override void OnDisable(){replay?.Stop();base.OnDisable();}
}
}
